# Batch 09 — Chapter VIII (Articles 77–84): remedies, liability and penalties.
def rt(u, origin, cp, rtype, obj, fn, mod, cond="", note="", deriv="direct", unres="", flag="", acc="", ext_dep="", dep=""):
    return qr(u, origin, cp, rtype, obj, fn, mod, cond=cond, deriv=deriv, type_note=note, unresolved=unres, flag=flag, acc=acc, ext=ext_dep, dep=dep)
CTRL, PROC, DS, SA, COMMN, MS, BD = "controller", "processor", "data subject", "supervisory authority", "European Commission", "Member States", "European Data Protection Board"
ORG = pd("not-for-profit body, organisation or association (Art.80)", "position_type", "A80.P1", note="Properly constituted under Member State law, statutory public-interest objectives, active in data protection; instances in national law.")
# 77
q = [rt("A77.P1", SA, DS, "review/adjudication", "right of every data subject to lodge a complaint with a supervisory authority (in particular where habitually resident, working, or the alleged infringement occurred)", "adjudication/dispute resolution (administrative complaint)", "entitlement", cond="the data subject considers that processing infringes the Regulation; without prejudice to other remedies", note="entitlement of the data subject against the SA; complements QR of Art.57(1)(f)", acc="candidate accountability relation of the SA toward complainants: see Arts 57(1)(f), 77(2), 78")]
screen("A77.P1", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A77.P2", SA, DS + " (complainant)", "information/reporting", "information on the progress and outcome of the complaint, including the possibility of a judicial remedy under Art.78", "information provision", "obligation", acc="ANSWERABILITY candidate (duty to inform on progress/outcome to an identified forum; judicial assessment and consequences in Art.78; questioning capacity of the complainant not stated)", note="same duty as Art.57(1)(f) and Art.60(7)")]
screen("A77.P2", "Yes", "relation-bearing", qr=q, status="Extracted")
link("qr", "object", "handling complaints, investigating", "A77.P1;A77.P2")
# 78
q = [rt("A78.P1", COURT_ := "judicial authorities / courts (Member State)", SA, "review/adjudication", "effective judicial remedy against a legally binding decision of a supervisory authority concerning a natural or legal person", "adjudication (judicial review)", "entitlement", cond="legally binding decision of an SA concerning them; without prejudice to administrative or non-judicial remedies", note="gov-direction: courts review SA decisions; entitlement of natural or legal persons; content of the remedy is set by national procedural law", ext_dep="Member State law (courts, remedies)", acc="ACCOUNTABILITY candidate: forum = courts of the Member State; assessment/judgment and consequence (remedy) present by institution; duty to explain/justify and questioning capacity not stated except Art.78(4); remedy content outside W => evidential sufficiency: indeterminate"),
     rt("A78.P2", COURT_, SA, "review/adjudication", "effective judicial remedy where the competent SA (Arts 55–56) does not handle a complaint or does not inform the data subject within three months on progress or outcome", "adjudication (judicial review of inaction)", "entitlement", cond="three-month period; complaint under Art.77", ext_dep="Member State law (courts, remedies)")]
screen("A78.P1", "Yes", "relation-bearing; external-dependency", qr=[q[0]], status="Extracted", note="Judicial review of SA decisions; remedy content depends on national law.")
screen("A78.P2", "Yes", "relation-bearing; external-dependency", qr=[q[1]], status="Extracted", note="Remedy for SA inaction.")
n = na("A78.P3", "proceedings against a supervisory authority (parties)", "be brought before the courts of the Member State where the supervisory authority is established", "forum for review of SA decisions", "adjudication (jurisdiction rule)", "obligation", cp_status="none", counterpart=COURT_, flag="subject-unstated")
screen("A78.P3", "Yes", "operative-assignment (jurisdiction)", na=[n], status="Extracted", note="Jurisdiction rule: national courts of the SA's Member State.")
q = [rt("A78.P4", SA, COURT_, "information/reporting", "forwarding to the court of the Board's opinion or decision in the consistency mechanism that preceded the SA decision under challenge", "information provision (to the reviewing forum)", "obligation", cond="proceedings against a decision of an SA preceded by an opinion or decision of the Board", dep="consistency mechanism (Art.63)", acc="ANSWERABILITY element: duty to supply to the reviewing forum the antecedent Board opinion/decision (a duty of explanation toward the forum, here limited)", note="coupling between the consistency mechanism and national judicial review")]
screen("A78.P4", "Yes", "relation-bearing; procedural-dependency", qr=q, status="Extracted", note="Links Chapter VII (Board) to national judicial review.")
# 79
q = [rt("A79.P1", COURT_, CTRL + " / " + PROC, "review/adjudication", "effective judicial remedy for a data subject whose rights were infringed through non-compliant processing", "adjudication (civil/administrative remedy)", "entitlement", cond="without prejudice to administrative remedies incl. the complaint under Art.77", ext_dep="Member State law (courts, remedies)", note="gov-direction: courts adjudicate disputes between data subject and controller/processor; entitlement of the data subject")]
screen("A79.P1", "Yes", "relation-bearing; external-dependency", qr=q, status="Extracted")
n = na("A79.P2", "proceedings against a controller or processor (parties)", "be brought before the courts of the Member State where the controller/processor has an establishment, or alternatively where the data subject habitually resides (unless a public authority acting in its public powers)", "forum for remedies against controllers/processors", "adjudication (jurisdiction rule)", "obligation", cp_status="none", counterpart=COURT_, flag="subject-unstated")
screen("A79.P2", "Yes", "operative-assignment (jurisdiction)", na=[n], status="Extracted")
# 80
q = [rt("A80.P1", ORG, DS, "representation/participation", "data subject's right to mandate a qualifying not-for-profit body to lodge a complaint, to exercise the rights in Arts 77–79 and, where provided by Member State law, to receive compensation under Art.82 on his or her behalf", "representation", "entitlement", cond="body properly constituted under Member State law, statutory objectives in the public interest, active in data protection; compensation only where provided by Member State law", note="gov-direction: body represents the data subject (mandate)", ext_dep="Member State law (constitution of bodies; compensation representation)")]
screen("A80.P1", "Yes", "relation-bearing", qr=q, pos=[ORG], status="Extracted")
q = [rt("A80.P2", ORG, SA + " and courts", "representation/participation", "right of the body, independently of a data subject's mandate, to lodge a complaint with the competent SA and exercise the rights in Arts 78–79", "representation (collective action)", "permission", cond="Member States may so provide; the body considers that rights of a data subject have been infringed", ext_dep="Member State law", note="optional by Member State law (N3-like competence)")]
screen("A80.P2", "Yes", "relation-bearing; external-dependency", qr=q, status="Extracted", note="Optional collective complaint right (Member State option).")
# 81
q = [rt("A81.P1", "competent court of a Member State", "court in another Member State", "information/reporting", "contact to confirm the existence of pending proceedings on the same subject matter regarding the same controller/processor", "cooperation/coordination (courts)", "obligation", cond="the court has information on such proceedings", note="court-to-court coordination")]
screen("A81.P1", "Yes", "relation-bearing", qr=q, pos=["PD-"] if False else [], status="Extracted")
q = [rt("A81.P2", "competent court other than the court first seized", "court first seized", "authority/control", "suspension of proceedings pending in another Member State on the same subject matter", "adjudication (procedural)", "permission"),
     rt("A81.P3", "court other than the court first seized", "court first seized", "authority/control", "declining jurisdiction on the application of a party where the court first seized has jurisdiction and its law permits consolidation", "adjudication (procedural)", "permission", cond="proceedings pending at first instance; application by a party; first court has jurisdiction and its law permits consolidation")]
screen("A81.P2", "Yes", "relation-bearing", qr=[q[0]], status="Extracted")
screen("A81.P3", "Yes", "relation-bearing", qr=[q[1]], status="Extracted")
# 82
q = [rt("A82.P1", CTRL + " / " + PROC, "any person who suffered damage", "beneficiary/protective", "right to receive compensation for material or non-material damage resulting from an infringement", "remediation (compensation)", "entitlement", note="liability relation; counterpart is any person (not only the data subject)")]
screen("A82.P1", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A82.P2", CTRL, "damage (liability allocation)", "contractual/exchange", "controller involved in processing liable for damage caused by infringing processing; processor liable only for breach of processor-specific obligations or acting outside or contrary to lawful instructions", "remediation (liability allocation)", "obligation", cond="processor: non-compliance with processor-specific obligations or acting outside/contrary to lawful instructions", note="liability allocation between controller and processor", flag="no-counterpart-position")]
screen("A82.P2", "Yes", "relation-bearing", qr=[q[0]], status="Extracted", note="Counterpart is damage/any injured person (see 82(1)); liability allocation between controller and processor.")
n = na("A82.P3", CTRL + " / " + PROC, "be exempt from liability if it proves it is not in any way responsible for the event giving rise to the damage", "exemption from liability", "remediation (exemption)", "exemption", cp_status="none", cond="proof of non-responsibility")
screen("A82.P3", "Yes", "operative-assignment", na=[n], status="Extracted")
q = [rt("A82.P4", CTRL + " / " + PROC + " (each of several involved)", "injured person", "beneficiary/protective", "each controller or processor liable for the entire damage in order to ensure effective compensation", "remediation (joint and several liability)", "obligation", cond="more than one controller/processor involved in the same processing and responsible for the damage")]
screen("A82.P4", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A82.P5", CTRL + " / " + PROC + " (that paid full compensation)", CTRL + " / " + PROC + " (other involved)", "contractual/exchange", "right to claim back the part of the compensation corresponding to the other's part of responsibility", "remediation (recourse)", "entitlement", cond="full compensation paid under 82(4)")]
screen("A82.P5", "Yes", "relation-bearing", qr=q, status="Extracted")
n = na("A82.P6", "court proceedings for compensation (parties)", "be brought before the courts competent under the law of the Member State referred to in Art.79(2)", "forum for compensation claims", "adjudication (jurisdiction rule)", "obligation", cp_status="none", flag="subject-unstated")
screen("A82.P6", "Yes", "operative-assignment (jurisdiction)", na=[n], status="Extracted")
# 83
n = na("A83.P1", SA, "ensure that administrative fines are in each individual case effective, proportionate and dissuasive", "administrative fines", "enforcement", "obligation", cp_status="none")
screen("A83.P1", "Yes", "operative-assignment", na=[n], status="Extracted")
q = [rt("A83.P2", SA, CTRL + " / " + PROC, "authority/control", "imposition of administrative fines in addition to or instead of the Art.58(2)(a)-(h),(j) measures, having due regard to factors (a)-(k)", "enforcement (sanction)", "competence", cond="depending on the circumstances of each case; due regard to nature, gravity, duration, intent, mitigation, responsibility under Arts 25 and 32, previous infringements, cooperation, categories of data, manner in which it became known, compliance with earlier measures, adherence to approved codes (Art.40) or certification (Art.42), other factors", dep="Art.58(2); Arts 25, 32; Arts 40, 42", note="Adherence to codes/certification is a mitigating factor: couples enforcement with the Section 5 instruments (cross-chapter dependency)")]
screen("A83.P2", "Yes", "relation-bearing; device-referencing", qr=q, status="Extracted", note="Fine-setting criteria include adherence to approved codes of conduct and certification.")
n = na("A83.P3", SA, "cap the total administrative fine for linked infringements at the amount specified for the gravest infringement", "cumulation of fines", "enforcement (limit)", "prohibition", cp_status="none", cond="intentional or negligent infringement of several provisions for the same or linked processing operations")
screen("A83.P3", "Yes", "operative-assignment (limit)", na=[n], status="Extracted")
n = na("A83.P4", SA, "impose administrative fines up to EUR 10 000 000 or 2 % of worldwide annual turnover (whichever higher) for infringements of: (a) obligations of controllers and processors under Arts 8, 11, 25–39, 42, 43; (b) obligations of certification bodies under Arts 42–43; (c) obligations of monitoring bodies under Art.41(4)", "fine tier 1", "enforcement (sanction)", "competence", cp_status="none", note="The tier names certification bodies (b) and monitoring bodies (c) as addressees of obligations sanctionable by SA fines: SA -> certification body and SA -> monitoring body relations by derivation.", flag="derived-relation")
q = [rt("A83.P4", SA, "certification body (Art.43)", "authority/control", "administrative fines for infringements of the certification body's obligations under Arts 42 and 43", "enforcement (sanction)", "competence", deriv="derived", dep="Art.83(2); Arts 42–43", unres="the fine tier of 83(4)(b) presupposes an SA power over certification bodies; the power to impose fines is conferred by 58(2)(i) and 83"),
     rt("A83.P4", SA, "code-monitoring body (Art.41)", "authority/control", "administrative fines for infringements of the monitoring body's obligations under Art.41(4)", "enforcement (sanction)", "competence", deriv="derived", dep="Art.83(2); Art.41(4)"),
     rt("A83.P4", SA, CTRL + " / " + PROC, "authority/control", "administrative fines up to EUR 10 000 000 / 2 % for infringements of Arts 8, 11, 25–39, 42, 43", "enforcement (sanction)", "competence", dep="Art.83(2)")]
screen("A83.P4", "Yes", "relation-bearing (derived for bodies)", na=[n], qr=q, status="Extracted", note="Tier 1 fines extend sanctioning to certification and monitoring bodies (derived from the list of infringed provisions).")
n = na("A83.P5", SA, "impose administrative fines up to EUR 20 000 000 or 4 % of worldwide annual turnover for infringements of: (a) Arts 5, 6, 7, 9; (b) Arts 12–22; (c) Arts 44–49; (d) obligations under Member State law adopted under Chapter IX; (e) non-compliance with a limitation/suspension order or failure to provide access in violation of Art.58(1)", "fine tier 2", "enforcement (sanction)", "competence", cp_status="none")
q = [rt("A83.P5", SA, CTRL + " / " + PROC, "authority/control", "administrative fines up to EUR 20 000 000 / 4 % for infringements listed in (a)-(e)", "enforcement (sanction)", "competence", dep="Art.83(2)")]
screen("A83.P5", "Yes", "relation-bearing", na=[n], qr=q, status="Extracted")
q = [rt("A83.P6", SA, CTRL + " / " + PROC, "authority/control", "administrative fines up to EUR 20 000 000 / 4 % for non-compliance with an Art.58(2) order", "enforcement (sanction)", "competence", cond="non-compliance with an order of the SA under Art.58(2)", dep="Art.58(2)")]
screen("A83.P6", "Yes", "relation-bearing", qr=q, status="Extracted")
n = na("A83.P7", MS, "may lay down rules on whether and to what extent administrative fines may be imposed on public authorities and bodies established in the Member State", "fines on public authorities", "enforcement (scope rule)", "permission (competence)", cond="without prejudice to Art.58(2) corrective powers", cp_status="none", dep="Member State law")
screen("A83.P7", "Yes", "operative-assignment (competence)", na=[n], status="Extracted")
n = na("A83.P8", SA, "exercise its powers under Art.83 subject to appropriate procedural safeguards in accordance with Union and Member State law, including effective judicial remedy and due process", "safeguards on fines", "review (constraint)", "obligation", cp_status="none", dep="Art.78")
screen("A83.P8", "Yes", "operative-assignment (constraint)", na=[n], status="Extracted")
q = [rt("A83.P9", SA, "competent national courts", "authority/control", "initiation of fines to be imposed by national courts where the Member State legal system does not provide for administrative fines; fines must be effective, proportionate and dissuasive", "enforcement (initiation before courts)", "competence", cond="the legal system of the Member State does not provide for administrative fines", ext_dep="Member State law (court-imposed fines)", note="gov-direction: SA initiates, courts impose"),
     rt("A83.P9", MS, COMMN, "information/reporting", "notification of the provisions adopted pursuant to 83(9) by 25 May 2018 and of any subsequent amendment", "information provision", "obligation", cond="Member States whose legal system does not provide for administrative fines")]
screen("A83.P9", "Yes", "relation-bearing; external-dependency", qr=q, status="Extracted")
# 84
n = na("A84.P1", MS, "lay down the rules on other penalties for infringements not subject to administrative fines and take all measures to ensure that they are implemented; penalties effective, proportionate and dissuasive", "other penalties", "enforcement (rule-making)", "obligation", cp_status="none", dep="Member State law")
q = [rt("A84.P2", MS, COMMN, "information/reporting", "notification of the provisions adopted pursuant to 84(1) by 25 May 2018 and any subsequent amendment", "information provision", "obligation")]
screen("A84.P1", "Yes", "operative-assignment", na=[n], status="Extracted")
screen("A84.P2", "Yes", "relation-bearing", qr=q, status="Extracted")
